mapper.sql:
FROM la_activity_signup s
LEFT JOIN la_activity a ON a.id = s.activity_id
LEFT JOIN la_area ar ON ar.id = a.area_id
LEFT JOIN la_recharge_order o ON o.id = s.order_id
LEFT JOIN la_user u ON u.id = s.user_id
LEFT JOIN la_student st ON st.id = s.student_id
WHERE 1 = 1

    AND s.activity_id = #{activityId}


    AND s.status = #{status}




            AND (s.order_id IS NULL OR s.order_id = 0 OR o.id IS NULL)


            AND s.order_id > 0 AND o.id IS NOT NULL AND o.pay_status = #{payStatus}




    AND s.create_time >= #{dateStart}


    AND s.create_time < #{dateEnd}


    AND (
        u.mobile LIKE #{keyword}
        OR u.real_name LIKE #{keyword}
        OR u.nickname LIKE #{keyword}
        OR st.name LIKE #{keyword}
        OR o.sn LIKE #{keyword}
        OR a.title LIKE #{keyword}
    )
